learn=[('Distinguish four execution paths', 'Agent SDK and Claude Code CLI supply a local agent runtime. A Client SDK calls the Messages API; your application dispatches tools. Managed Agents hosts the harness and retains session events server-side.'), ('Create a Managed Agents lifecycle', 'Create a dedicated agent, cloud environment and session; open the event stream, send a user event and observe the native idle event after the reply. The model key stays on the server.'), ('Compare ownership before benchmarks', 'Inspect who owns the loop, process, tools and state. Run the same small expense policy on two platforms, but do not infer general quality, latency or price rankings from one classroom sample.'), ('Choose from workload constraints', 'Embedded callbacks and in-process tools favor operating the Agent SDK. Long asynchronous work may fit Managed Agents. Conflicting retention requirements need review before a platform choice; neither a label nor local hosting guarantees compliance.'), ('Review historical SDK migration', 'Inspect an obsolete import as text, replace the package reference and review explicit prompts, settings, tools and permissions. The old package is never installed. A real modern SDK run checks the small regression task.'), ('Map primitives and verify state', 'Port a small function into an actual tool() / MCP handler, observe a real hook and distinguish delegation from conversation handoff. Compare SDK session_id/resume with a remote retained Managed session. Working files need their own persistence plan.')]
labels=[('sdk', 'Agent SDK: local runtime owns the loop'), ('cli', 'Claude Code CLI: actual headless process'), ('client', 'Client SDK: application dispatches a tool'), ('managed', 'Managed Agents: hosted lifecycle and events'), ('compare', 'Same task on SDK and Managed Agents'), ('decision', 'Workload and retention decision guide'), ('legacy', 'Review a Claude Code SDK migration'), ('toolport', 'Port a function tool and hook'), ('session', 'Compare local resume and remote sessions')]
runsteps=[('Prerequisites', 'Use Node.js 24+, model API credit and a model available to your account. Native Windows may require Git Bash. Docker, a GitHub token and an OpenAI API key are not required. Managed Agents is currently beta; verify current availability and data policies before production use.', 'node --version\nnpm --version'), ('Install and configure privately', 'From presentations use the path below; skip cd in a standalone clone. Preserve an existing .env and enter your key privately. The same key is used server-side for the Agent SDK, CLI, Client SDK and Managed Agents. No existing agent or environment ID is required.', 'cd .\\agent-sdk\\lesson59-platform-migrations\nnpm ci\nif (!(Test-Path .env)) { Copy-Item .env.example .env }\nnotepad .env'), ('Start the five-page lab', 'Keep the terminal open, visit each student section and start with Agent SDK. Then compare CLI and Client SDK ownership. The browser accepts fixed experiment names only; it cannot supply commands, paths or remote resource IDs.', 'npm start\n# http://127.0.0.1:3159'), ('Run source and migration checks', 'Unit tests verify policy boundaries, fixed inputs, retention conflicts and the historical source transformation without a model call. Legacy fixtures are never evaluated or installed.', 'npm test'), ('Compare real execution paths', 'These commands make real model requests. Managed modes create dedicated short-lived resources, delete their own sessions/environments and archive their own agent configuration. IDs are journalled privately under .runtime for audit. Existing lesson resources are never used or changed.', 'npm run pipeline -- sdk\nnpm run pipeline -- cli\nnpm run pipeline -- client\nnpm run pipeline -- managed\nnpm run eval'), ('Inspect migrations, state and cleanup', 'Toolport executes the actual modern Claude tool/MCP/hook path, not OpenAI. Session makes four actual turns and compares recall of an unpredictable code. The SDK transcript lives in a temporary local workspace; Managed history is remote until cleanup. No cron schedule, public service, payment or remote business-system integration is created.', 'npm run pipeline -- decision\nnpm run pipeline -- legacy\nnpm run pipeline -- toolport\nnpm run pipeline -- session\nnpm run cleanup\n# .runtime/runs/<run-id>/evidence.json\n# .runtime/managed-resources/<owner-id>.json')]
specs=[('Choose a fixed experiment', 'src/protocol.ts', 'if (', 'The browser selects a reviewed experiment. Validate the mode and reject arbitrary commands, paths and foreign session IDs.', 0, 1, 8), ('Configure the local SDK boundary', 'src/local.ts', 'const options: Options', 'Run the SDK in a fresh temporary workspace with explicit settings, tools, permissions and finite limits. The SDK runtime owns local orchestration; these settings are not a complete operating-system sandbox.', 1, 2, 9), ('Run the actual Agent SDK loop', 'src/local.ts', 'const run = query', 'Consume real SDK messages and terminal results. In-process MCP mode keeps streaming input open while the tool handler runs. A new query can resume a retained local session ID.', 1, 2, 8), ('Invoke the actual headless CLI', 'src/local.ts', 'const p = await runProcess', 'Spawn the installed native CLI without a shell, pass fixed arguments and observe its actual exit code. The private launching environment supplies the API key; stdout contains native JSON.', 1, 2, 8), ('Make a Client SDK model request', 'src/client-loop.ts', 'const message = await client.messages.create', 'The Client SDK sends a Messages request and returns content blocks. It does not execute application business functions for you. This app bounds the tool loop to three rounds.', 1, 3, 8), ('Dispatch a tool and preserve its ID', 'src/client-loop.ts', 'for (const use of uses)', 'Validate the requested tool name and its amount, call trusted business logic, then return a tool_result linked to the original tool_use ID. This dispatch loop belongs to the application.', 1, 3, 9), ('Create a dedicated hosted agent', 'src/managed.ts', 'const agent = await', 'Create only this experiment’s named agent with no tools for the text-only comparison. The official Client SDK calls the Managed Agents API; Anthropic hosts the harness.', 1, 4, 9), ('Create the cloud environment', 'src/managed.ts', 'const environment = await', 'Create a dedicated limited-network cloud configuration and journal its new ID immediately. No supplied IDs from older lessons or other users are accepted.', 1, 4, 9), ('Create a bounded retained session', 'src/managed.ts', 'const session = await', 'Reference the new agent and environment. The Managed budget uses integer USD minor units: amount 50 means fifty cents, not fifty dollars. Its list-cost limit differs from the SDK estimate threshold.', 1, 4, 10), ('Open observation before sending', 'src/managed.ts', 'let stream = await', 'Open the actual session SSE stream before sending the user event. Observe native event IDs and avoid replaying already seen events across turns.', 1, 4, 7), ('Observe the hosted answer', 'src/managed.ts', 'if (event.type === "agent.message")', 'Render actual agent.message text and wait for a real idle event after the reply. Do not treat an initial idle status or a local fake result as a completed hosted turn.', 4, 1, 8), ('Review a small legacy transformation', 'src/migrations.ts', 'const after = before', 'Transform a historical fixture as text and review explicit modern configuration. This is a narrow illustration, not a general codemod. The separate modern SDK runner executes the regression task.', 1, 2, 8), ('Grade the task and owned cleanup', 'src/runner.ts', 'checks.ownedResourcesCleaned', 'Require observed native success and experiment-specific checks, including actual handlers, recall or cleanup. SDK, CLI, Messages and Managed result shapes remain distinct in the evidence.', 1, 0, 6)]
reference=[('What is real', 'All nine modes make actual model calls. SDK invokes query; CLI spawns the native runtime; Client SDK implements its own tool dispatch; Managed modes create real remote resources and consume actual events. No response is simulated.'), ('Four choices, four responsibilities', 'Agent SDK and CLI share a local runtime family, but their invocation surfaces differ. A Client SDK is an API library and needs an application tool loop. Managed Agents moves harness operation and retained session events to Anthropic. Its sandbox may be cloud or self-hosted; this app demonstrates a cloud configuration.'), ('State and cost are not interchangeable', 'Session IDs belong to different systems and are never reused across platforms. Local SDK transcripts need a persistence design to outlive the workspace; Managed history is server-side. Native usage and budget shapes differ. This app preserves them without inventing a universal billed total or an apples-to-apples benchmark.'), ('Retention and beta status', 'Reviewed 2026-10-26: the official Managed Agents overview lists the managed-agents-2026-04-01 beta header and states the feature is not currently ZDR-eligible or covered by HIPAA BAA. Verify the current policy before a deployment decision. Operating the SDK locally does not automatically make API traffic or retained data compliant.'), ('Migration is a behavioral port', 'Legacy demonstrates selected import/configuration edits and executes the modern regression task. Toolport maps a small business function to a real Claude MCP handler and hook. OpenAI fixture code is not installed or executed. Subagent delegation is not claimed to be identical to a conversation handoff.'), ('Owned resources and interruptions', 'The app journals IDs it creates, deletes its own Managed sessions and environments, and archives its agent configuration. Archived metadata remains on the platform. Normal failures and cancellations attempt cleanup; a hard host crash or network outage can leave IDs in the private journal for operator review. No existing lesson resources are modified. The bounded observation recovery reads native history after opening a replacement stream; it never resends an accepted user event. Run npm run cleanup to recover ownership-verified non-empty journals after an outage.'), ('Primary references', 'https://platform.claude.com/docs/en/managed-agents/overview ; https://platform.claude.com/docs/en/managed-agents/quickstart ; https://platform.claude.com/docs/en/agent-sdk/overview ; https://platform.claude.com/cookbook/claude-agent-sdk-04-migrating-from-openai-agents-sdk ; https://platform.claude.com/docs/en/agent-sdk/migration-guide ; Original deck: Lesson59_Agent_SDK_vs_Managed_Agents_and_Migrations.pptx')]

env="ANTHROPIC_API_KEY=your_api_key\nCLAUDE_MODEL=claude-sonnet-4-6\nPORT=3159\n# CLAUDE_CODE_GIT_BASH_PATH=C:/Program Files/Git/bin/bash.exe"
select=''.join(f'<option value="{m}">{escape(t)}</option>' for m,t in labels)
body='<section class="panel" id="controls"><h2>Run a platform or migration experiment</h2><p id="configuration">Checking configuration...</p><label for="mode">Experiment</label><select id="mode">'+select+'</select><div class="actions"><button class="primary" id="run" disabled>Run real platform experiment →</button><button id="download">Download actual evidence</button></div><p class="note">Run real SDK, CLI, Messages or Managed requests. Managed modes create dedicated remote resources and clean up only their own IDs. Legacy examples are text fixtures, not installed packages.</p><p id="status" role="status">Choose an experiment.</p></section>'
body+='<div class="grid"><article class="card"><h3>Actual worker exit</h3><p id="span-count">Pending</p></article><article class="card"><h3>Native results</h3><p id="metric-count">0</p></article><article class="card"><h3>Native paths observed</h3><p id="log-count">0</p></article></div>'
body+='<div class="workspace"><section class="panel" id="chat-panel"><h2>Actual formatted agent responses</h2><div id="conversation" class="markdown-body"></div></section><section class="panel" id="option-panel"><h2>Actual SDK configuration</h2><pre class="json-view"><code id="options" class="language-json">{}</code></pre></section></div>'
def panel(id,title,code):return f'<section class="step" id="{id}"><h2>{title}</h2><pre class="json-view"><code id="{code}" class="language-json">{{}}</code></pre></section>'
body+='<p class="note" id="boundary-summary">Observe who owns the loop and state. Legacy fixtures are illustrations; native modern paths run live.</p>'
body+=panel('process-panel','Actual process exit and case-level report','process')
body+='<section class="step" id="artifact-panel"><h2>Platform ownership and migration evidence</h2><pre><code id="diff" class="language-json">Waiting for a real evaluation.</code></pre><pre class="json-view"><code id="host-checks" class="language-json">{}</code></pre></section>'
def tablepanel(id,title,heads,target,extra=''):
 return f'<section class="step" id="{id}"><h2>{title}</h2>'+extra+'<div class="table"><table><thead><tr>'+''.join('<th>'+h+'</th>'for h in heads)+f'</tr></thead><tbody id="{target}"></tbody></table></div></section>'
body+=tablepanel('trace-panel','Actual native-path and tool observations',['Event','Status / entries','Observed detail'],'trace-history')
body+=tablepanel('metric-panel','Observed checks and native usage scope',['Case','Passed / runs','Measurements and uncertainty'],'metric-history')
body+=tablepanel('model-panel','Actual harness observations',['Stage','Evidence'],'log-history','<label for="user-filter">Filter by exact observation kind</label><input id="user-filter" placeholder="configuration">')
for id,title,code in [('results-panel','Actual final native result','native-result'),('storage-panel','State and migration provenance','storage'),('diagnostic-panel','Incomplete runs and grader reasons','diagnostics'),('evidence-panel','All actual evaluation evidence','evidence'),('specialists-panel','All actual observations','telemetry'),('requests-panel','Native tool requests','requests')]:body+=panel(id,title,code)
document('/','Compare platforms. <em>Migrate deliberately.</em>','Four execution paths, workload decisions and small verified migration examples.',body,'<script type="module" src="/client.js"></script>')
document('/learn.html','What you <em>will learn.</em>','Choose who operates the harness and verify the behavior you port.',(APP/'scripts/platform-table.html').read_text(encoding='utf-8')+cards(learn)+actions(('/','Application lab'),('/run.html','How to run')))
run=''
for i,(title,text,code) in enumerate(runsteps,1):run+=f'<section class="step" id="run-step-{i}"><span class="number">{i:02}</span><h2>{escape(title)}</h2><p>{escape(text)}</p>'+snippet(code,'powershell')+(snippet(env,'ini')if i==2 else '')+'</section>'
document('/run.html','Configure and <em>run the app.</em>','Preserve your private .env. Start locally, then inspect real grades and reports.',run)
import re
steps=[];arrows=[];lanes=['Student','Web host','SDK / CLI','Client SDK','Managed API']
for n,(title,source,anchor,explanation,a,b,count) in enumerate(specs,1):
 text=(APP/source).read_text(encoding='utf-8');lines=text.splitlines();idx=next(i for i,l in enumerate(lines) if re.sub(r"\s+", "", anchor) in re.sub(r"\s+", "", l))
 code='\n'.join(lines[idx:idx+count]).strip()
 steps.append(dict(number=n,title=title,source=source,code=code,language='yaml' if source.endswith('.yml') else 'javascript' if source.endswith('.js') else 'docker' if source=='Dockerfile' else 'typescript',explanation=explanation,firstLine=idx+1,lastLine=idx+count,anchors=[lines[idx].strip()],sourceSHA256=hashlib.sha256(text.encode()).hexdigest(),narration=f'Step {n}. {explanation} This source excerpt shows the corresponding application statement.'))
 arrows.append([a,b,f'{n}. {title}'])
(APP/'scripts/architecture-data.json').write_text(json.dumps(dict(lanes=lanes,arrows=arrows,steps=steps),indent=2),encoding='utf-8')
xs=[170,520,870,1220,1570];svg=['<svg xmlns="http://www.w3.org/2000/svg" width="1740" height="1600" viewBox="0 0 1740 1600"><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="8" markerHeight="8" orient="auto"><path d="M0 0 L10 5 L0 10z" fill="#087fff"/></marker></defs><rect width="1740" height="1600" fill="#f4f9ff"/><text x="40" y="52" font-family="Arial" font-size="34" fill="#101a44">Lesson 59 · Compare → choose → migrate → verify</text>']
for x,label,colour in zip(xs,lanes,['#087fff','#8838ff','#00a977','#8838ff','#ee5425']):svg.append(f'<rect x="{x-150}" y="90" width="300" height="80" rx="16" fill="{colour}"/><text x="{x}" y="139" text-anchor="middle" font-family="Arial" font-size="27" fill="white">{escape(label)}</text><path d="M{x} 170 V1550" stroke="#aec6df" stroke-dasharray="8 7"/>')
for i,(a,b,label) in enumerate(arrows):
 x1,x2=xs[a],xs[b];y=245+i*98;path=f'M{x1} {y} h65 v24 h-65' if a==b else f'M{x1} {y} H{x2}';svg.append(f'<text x="{max(40,min(min(x1,x2)+10,1700-len(label)*13))}" y="{y-18}" fill="#142d53" font-family="Arial" font-size="24">{escape(label)}</text><path d="{path}" stroke="#087fff" stroke-width="3" marker-end="url(#arrow)"/>')
(PUBLIC/'architecture.svg').write_text(''.join(svg)+'</svg>',encoding='utf-8')
walk=''
for s in steps:walk+=f'<section class="step workflow-step" id="workflow-step-{s["number"]:02}"><span class="number">{s["number"]:02}</span><h3>{s["number"]}. {s["title"]}</h3><p>{escape(s["explanation"])}</p><p class="source">Source: {s["source"]} · lines {s["firstLine"]}–{s["lastLine"]} · selected source; surrounding code omitted</p>'+snippet(s['code'],s['language'])+'</section>'

document('/architecture.html','Architecture and <em>UML workflow.</em>','Every one of the thirteen steps includes matching coloured source code.','<p class="note">The host dispatches four distinct native paths. Local SDK and CLI runtimes, a handwritten Client SDK tool loop, and a hosted Managed Agents harness have different ownership and state boundaries. Every workflow step includes matching source.</p><a class="button" href="/architecture.svg" download>Download UML SVG</a><div class="diagram"><img src="/architecture.svg" alt="Thirteen-step evaluation harness sequence"></div>'+walk)
